use std::panic;

#[derive(Debug, PartialEq)]
enum Outcome {
    Passed,
    Failed(String),
    Ignored,
}

struct TestCase {
    name: &'static str,
    ignored: bool,
    body: fn(),
}

fn message(payload: Box<dyn std::any::Any + Send>) -> String {
    if let Some(s) = payload.downcast_ref::<&str>() {
        s.to_string()
    } else if let Some(s) = payload.downcast_ref::<String>() {
        s.clone()
    } else {
        "panic".to_string()
    }
}

fn run_tests(tests: &[TestCase], filter: &str) -> Vec<(String, Outcome)> {
    let previous = panic::take_hook();
    panic::set_hook(Box::new(|_| {}));
    let results = tests
        .iter()
        .filter(|t| t.name.contains(filter))
        .map(|t| {
            let outcome = if t.ignored {
                Outcome::Ignored
            } else {
                match panic::catch_unwind(t.body) {
                    Ok(()) => Outcome::Passed,
                    Err(payload) => Outcome::Failed(message(payload)),
                }
            };
            (t.name.to_string(), outcome)
        })
        .collect();
    panic::set_hook(previous);
    results
}

fn summary(results: &[(String, Outcome)]) -> String {
    let count = |want: fn(&Outcome) -> bool| results.iter().filter(|(_, o)| want(o)).count();
    let passed = count(|o| *o == Outcome::Passed);
    let failed = count(|o| matches!(o, Outcome::Failed(_)));
    let ignored = count(|o| *o == Outcome::Ignored);
    let status = if failed > 0 { "FAILED" } else { "ok" };
    format!("test result: {status}. {passed} passed; {failed} failed; {ignored} ignored")
}

unitTests:
fn adds() { assert_eq!(2 + 2, 4); }
fn bad_math() { assert_eq!(2 + 2, 5, "math is broken"); }
fn explicit() { panic!("value was {}", 42); }
fn literal() { panic!("plain text"); }
fn odd_payload() { std::panic::panic_any(7u8); }
fn slow() { panic!("should not run"); }

let suite = [
    TestCase { name: "math::adds", ignored: false, body: adds },
    TestCase { name: "math::bad_math", ignored: false, body: bad_math },
    TestCase { name: "panics::explicit", ignored: false, body: explicit },
    TestCase { name: "panics::literal", ignored: false, body: literal },
    TestCase { name: "panics::odd", ignored: false, body: odd_payload },
    TestCase { name: "slow::big", ignored: true, body: slow },
];

test("running a suite", || {
    let results = run_tests(&suite, "");
    check_eq(results.len(), 6);
    check_eq(&results[0], &("math::adds".to_string(), Outcome::Passed));
    check(matches!(&results[1].1, Outcome::Failed(m) if m.contains("math is broken")));
    check_eq(&results[2].1, &Outcome::Failed("value was 42".to_string()));
    check_eq(&results[3].1, &Outcome::Failed("plain text".to_string()));
    check_eq(&results[4].1, &Outcome::Failed("panic".to_string()));
    check_eq(&results[5].1, &Outcome::Ignored);
    check_eq(summary(&results), "test result: FAILED. 1 passed; 4 failed; 1 ignored");
});

test("filtering", || {
    let math = run_tests(&suite, "math");
    check_eq(math.len(), 2);
    let only_adds = run_tests(&suite, "adds");
    check_eq(summary(&only_adds), "test result: ok. 1 passed; 0 failed; 0 ignored");
    check_eq(summary(&run_tests(&suite, "nothing")), "test result: ok. 0 passed; 0 failed; 0 ignored");
});

